create table document_check_decision (id uuid primary key,lc_id uuid not null references letter_of_credit(id) on delete cascade,finding_code varchar(100) not null,document_name varchar(255) not null default '',decision varchar(30) not null,comment varchar(1000),reviewed_by varchar(100) not null,reviewed_at timestamp not null,constraint uk_document_check_decision unique (lc_id,finding_code,document_name));
